import{readSetting,writeSetting}from"./settings.js";export const CONTROL_MODES={tap:"Tap to move",dpad:"D-pad"};const DEFAULT_MODE="tap";export function createControlsSetting(getStorage){let mode=readSetting("controls",DEFAULT_MODE,getStorage);if(!(mode in CONTROL_MODES)){console.warn(`[controls] unknown saved mode "${mode}", using "${DEFAULT_MODE}"`);mode=DEFAULT_MODE}let folded=readSetting("dpadFolded",false,getStorage);return{mode:()=>mode,label:()=>CONTROL_MODES[mode],showsDpad:()=>mode==="dpad",dpadFolded:()=>folded,dpadView:()=>({pad:mode==="dpad"&&!folded,foldedButton:mode==="dpad"&&folded}),setDpadFolded(next){if(typeof next!=="boolean"){throw new Error(`the d-pad is folded or not, not ${JSON.stringify(next)}`)}folded=next;return writeSetting("dpadFolded",folded,getStorage)},set(next){if(!(next in CONTROL_MODES)){throw new Error(`unknown controls mode "${next}"`)}mode=next;return writeSetting("controls",mode,getStorage)},toggle(){return this.set(mode==="tap"?"dpad":"tap")}}}export function bindControlsButton(button,controls,{onChange}={}){const stateText=button.querySelector(".setting-state");function render(){if(stateText)stateText.textContent=controls.label();button.setAttribute("aria-label","Controls: "+controls.label())}button.addEventListener("click",ev=>{ev.preventDefault();controls.toggle();render();onChange?.(controls.mode())});render()}export function renderDpad(controls,{pad,showButton}){const view=controls.dpadView();pad.hidden=!view.pad;showButton.hidden=!view.foldedButton}export function bindDpadFold(controls,{pad,foldButton,showButton,onChange}){const fold=(next,pressed,replacement)=>ev=>{controls.setDpadFolded(next);renderDpad(controls,{pad,showButton});if(ev.detail===0||document.activeElement===pressed)replacement.focus({preventScroll:true});onChange?.(next)};foldButton.addEventListener("click",fold(true,foldButton,showButton));showButton.addEventListener("click",fold(false,showButton,foldButton))}
